#!/usr/bin/env python3
"""
Round 172b (culprits-tiles-more), 4 October 2026.

medical_culprits.py: unlinked repeat rows placed. forest500_map.py: a
country with no capital in Natural Earth placed at its largest place.
Whole files, each written only if it differs. Run from the repository root.
"""
import base64, pathlib

FILES = {
    "scripts/medical_culprits.py": "",
    "scripts/forest500_map.py": "",
}


def main():
    for name, data in FILES.items():
        p = pathlib.Path(name)
        new = base64.b64decode(data)
        if p.exists() and p.read_bytes() == new:
            print(f"round172b_tiles: {name} already up to date")
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(new)
        print(f"round172b_tiles: wrote {name}")


if __name__ == "__main__":
    main()
